#!/usr/bin/env bash
# Generated by studio/pipeline/render.py — do not edit by hand.
set -euo pipefail

command -v ffmpeg >/dev/null || { echo "ffmpeg not installed" >&2; exit 1; }
CLIPS="${CLIPS_DIR:-./clips}"
OUT="${OUT_DIR:-./out}"
mkdir -p "$OUT"

concat=$(mktemp)
echo "file '$CLIPS/s01.mp4'" >> "$concat"
echo "file '$CLIPS/s02.mp4'" >> "$concat"
