echo "file '$CLIPS/s13.mp4'" >> "$concat"
echo "file '$CLIPS/s14.mp4'" >> "$concat"
echo "file '$CLIPS/s15.mp4'" >> "$concat"
echo "file '$CLIPS/s16.mp4'" >> "$concat"
echo "file '$CLIPS/s17.mp4'" >> "$concat"
