echo "file '$CLIPS/s19.mp4'" >> "$concat"
echo "file '$CLIPS/s20.mp4'" >> "$concat"
echo "file '$CLIPS/s21.mp4'" >> "$concat"
echo "file '$CLIPS/s22.mp4'" >> "$concat"
echo "file '$CLIPS/s23.mp4'" >> "$concat"
